};
interface Step { label: string; status?: string; value?: unknown; error?: string; request?: unknown; reason?: string }
interface Row { condition: string; track: string; sourceRoot: string; artifactDir: string; configPath: string; steps: Step[] }
const result: {kind: string; conditions: Row[]; fixture: typeof fixture} = {kind: 'development-only-public-interface-calibration', conditions: [], fixture};
async function save() { await fs.writeFile(path.join(work, 'observations.json'), JSON.stringify(result, null, 2)+'\n'); }
async function capture(label: string, action: () => Promise<unknown>, row: Row) {
  try { const value = await action(); row.steps.push({label, status: 'completed', value}); await save(); return true; }
  catch (error) { row.steps.push({label, status: 'error', error: String(error)}); await save(); return false; }
}
for (const condition of conditions) {
  for (const track of ['conformance-public', 'file-discovery-public']) {
    const artifactDir = path.join(work, 'runs', condition, track), sourceRoot = path.join(artifactDir, 'source');
    await fs.mkdir(sourceRoot, {recursive: true});
    for (const [relative, content] of Object.entries(fixture)) { const target=path.join(sourceRoot,relative); await fs.mkdir(path.dirname(target),{recursive:true});await fs.writeFile(target,content); }
    const configPath=path.join(artifactDir,'ocbi-config.json');
    await fs.writeFile(configPath,JSON.stringify({embeddingProvider:'ollama',embeddingModel:'nomic-embed-text',indexing:{mode:condition==='ocbi-structural'?'structural':'hybrid',autoIndex:false,watchFiles:false,requireProjectMarker:false},reranker:{enabled:false}},null,2)+'\n');
    const row: Row={condition,track,sourceRoot,artifactDir,configPath,steps:[]};result.conditions.push(row);await save();
    const driver=track==='conformance-public'?createConformanceDriver(condition,{sourceRoot,artifactDir,toolsRoot,projectRoot,configPath,timeoutMs:60000}):createAdapter(condition,{projectRoot:sourceRoot,toolsRoot,ocbiCliPath:path.join(projectRoot,'dist/cli.js'),configPath,artifactDir});
    try {
      const indexed=await capture('index',()=>driver.index(),row);
      if (indexed) {
        if (track==='conformance-public') {
          const requests: ParticipantRequest[]=[
            {operation:'definitions',subject:{symbol:'calibrationLeaf',path:'src/leaf.js'},limit:50},
            {operation:'direct-callers',subject:{symbol:'calibrationLeaf',path:'src/leaf.js'},limit:50},
            {operation:'direct-callees',subject:{symbol:'calibrationEntry',path:'src/entry.js'},limit:50},
            {operation:'shortest-path',from:{symbol:'calibrationEntry',path:'src/entry.js'},to:{symbol:'calibrationLeaf',path:'src/leaf.js'},limit:50},
            {operation:'definitions',subject:{symbol:'calibrationDefinitelyAbsent'},limit:50},
          ];
          for (const request of requests) { row.steps.push({label:'request-input',request});await capture(request.operation+':'+(request.subject?.symbol??request.from?.symbol),()=> (driver as ConformanceDriver).request(request),row); }
        } else {
          for(const request of [{query:'calibrationLeaf',symbol:'calibrationLeaf',limit:50},{query:'increment a value by seven through an entry wrapper',limit:50},{query:'calibrationDefinitelyAbsent',symbol:'calibrationDefinitelyAbsent',limit:50}]) {row.steps.push({label:'query-input',request});await capture('query:'+request.query,()=> (driver as CompetitiveAdapter).query(request),row);}
        }
      } else {row.steps.push({label:'queries',status:'not-run',reason:'index prerequisite failed; no retry'});}
    } finally {await capture('close',()=>driver.close(),row);}
  }
}
