import { Client } from '${PROJECT}/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import { StdioClientTransport } from '${PROJECT}/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
import { writeFile } from 'node:fs/promises';
const work = '${WORK}';
const project = '${PROJECT}';
const observations=[];
for (const condition of ['ocbi-hybrid','ocbi-structural']) {
 const root=`${work}/runs/${condition}/conformance-public`, home=`${root}/home`;
 const env={PATH:process.env.PATH,HOME:home,XDG_CACHE_HOME:`${home}/.cache`,XDG_CONFIG_HOME:`${home}/.config`,XDG_STATE_HOME:`${home}/.state`,XDG_DATA_HOME:`${home}/.local/share`,TMPDIR:`${root}/tmp`,CBM_CACHE_DIR:`${root}/cbm-cache`,LANG:'C.UTF-8',LC_ALL:'C.UTF-8'};
 const args=[`${project}/dist/cli.js`,'--project',`${root}/source`,'--host','opencode','--config',`${root}/ocbi-config.json`];
 const transport=new StdioClientTransport({command:process.execPath,args,cwd:`${root}/source`,env,stderr:'pipe'});
 const record={condition,command:process.execPath,args,cwd:`${root}/source`,env,request:{name:'index_status',arguments:{}},stderr:''};
 transport.stderr?.on('data', chunk=>{record.stderr+=String(chunk);});
 const client=new Client({name:'development-readiness-calibration',version:'1'});
 try {await client.connect(transport);record.raw=await client.callTool(record.request,undefined,{timeout:60000});}
 catch(error){record.error=String(error);}
 finally{await client.close();await transport.close();observations.push(record);}
}
await writeFile(`${work}/readiness-observations.json`,JSON.stringify(observations,null,2)+'\n');
console.log(JSON.stringify(observations,null,2));

